const GLASS_STRENGTHS = new Set(['off', 'soft', 'standard', 'clear'])
const MOTIONS = new Set(['system', 'reduced'])
const PARTICLE_DENSITIES = new Set(['sparse', 'light', 'standard', 'dense', 'ultra'])
