const numeric = Number(value)
if (!Number.isFinite(numeric)) return fallback
const clamped = Math.min(PARTICLE_TRAVERSAL_SPEED_MAX, Math.max(PARTICLE_TRAVERSAL_SPEED_MIN, numeric))
